(function(root){
 'use strict';
 const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const labels={title:['المسمى الوظيفي','Position title'],field:['المجال الوظيفي','Field'],seniority:['المستوى المطلوب','Seniority'],department:['الإدارة','Department'],manager:['المدير المباشر','Reporting manager'],businessNeed:['مبرر الاحتياج','Business need'],alternatives:['البدائل المدروسة','Alternatives considered'],successMeasures:['مؤشرات النجاح','Success measures'],purpose:['هدف المنصب','Purpose'],responsibilities:['المسؤوليات','Responsibilities'],team:['نطاق الإشراف','Team and supervision'],budget:['نطاق الميزانية','Budget scope'],authority:['الصلاحيات','Decision authority'],impact:['نطاق الأثر','Impact'],stakeholders:['أصحاب العلاقة','Stakeholders'],qualifications:['المؤهلات','Qualifications'],experience:['الخبرة','Experience'],skills:['المهارات الفنية','Technical skills'],behaviors:['الجدارات السلوكية','Behavioral competencies'],headcount:['العدد المطلوب','Requested headcount'],annualCost:['التكلفة السنوية الإجمالية - ر.س','Total annual cost - SAR'],directReports:['عدد المرؤوسين','Direct reports'],occupationCode:['الرمز المهني','Occupation code'],occupationRelease:['إصدار المرجع','Reference edition'],educationLevel:['المستوى التعليمي','Education level'],educationFieldCode:['التخصص التعليمي','Education specialization'],constraints:['المحددات','Constraints'],mappingJustification:['مبرر المرجع المؤقت','Provisional mapping rationale'],provisionalParent:['الوحدة المرجعية الأب','Parent unit']};
 function body(content,locale='ar',record={}){
  const ar=locale==='ar',t=(a,b)=>ar?a:b;
  const fields=Object.entries(labels).filter(([key])=>key!=='title'&&content[key]!==undefined&&content[key]!=='').map(([key,label])=>'<section><h2>'+escape(label[ar?0:1])+'</h2><p>'+escape(content[key]).replace(/\n/g,'<br>')+'</p></section>').join('');
  const matrix=(title,rows,keys,headings)=>'<section><h2>'+title+'</h2>'+(rows?.length?'<div class="matrix"><table><thead><tr>'+headings.map(h=>'<th>'+escape(h)+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+keys.map(k=>'<td>'+escape(r[k])+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>':'<p>'+t('لم تُدخل بيانات.','No entries supplied.')+'</p>')+'</section>';
  return '<article class="position-report" lang="'+(ar?'ar':'en')+'" dir="'+(ar?'rtl':'ltr')+'"><header><strong>MI’YĀR / '+t('حزمة المنصب','POSITION PACKAGE')+'</strong><h1>'+escape(content.title||t('مسودة منصب','Position draft'))+'</h1><p>'+t('مسودة للمراجعة - غير معتمدة','Review draft - not approved')+'</p><p dir="ltr">'+escape(record.internalCode||'')+(record.revision?' · v'+record.revision:'')+'</p></header>'+fields+matrix('RACI',content.raci,['responsibility','R','A','C','I'],[t('المسؤولية','Responsibility'),'R','A','C','I'])+matrix(t('مصفوفة الجدارات','Competency matrix'),content.skillRequirements,['name','type','level','evidence'],[t('المهارة','Skill'),t('النوع','Type'),t('المستوى','Level'),t('الدليل','Evidence')])+'<footer>'+t('مخرجات محلية للمراجعة. اعتماد المنصب يتطلب مسار المؤسسة وحسابات المراجعين.','Local review output. Approval requires the organization workflow and reviewer accounts.')+'</footer></article>';
 }
 const style='body{margin:0;background:#fff;color:#153b42;font:16px/1.8 Arial,sans-serif}.position-report{max-width:850px;margin:auto;padding:36px;overflow-wrap:anywhere}.position-report header{border-bottom:3px solid #16735b;padding-bottom:20px}.position-report h1{font-size:28px;line-height:1.5}.position-report h2{font-size:18px;margin:24px 0 6px}.position-report p{margin:0 0 8px}.position-report table{border-collapse:collapse;width:100%;font-size:14px}.position-report td,.position-report th{padding:10px;border:1px solid #dce8e3;text-align:start;vertical-align:top}.position-report footer{margin-top:32px;border-top:1px solid #dce8e3;padding-top:16px;font-size:13px}.matrix{overflow-x:auto}@page{size:A4;margin:15mm}@media print{.position-report{padding:0}h2{break-after:avoid}tr{break-inside:avoid}}@media(max-width:600px){.position-report{padding:18px}}';
 function html(content,locale,record){return '<!doctype html><html lang="'+(locale==='en'?'en':'ar')+'" dir="'+(locale==='en'?'ltr':'rtl')+'"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+escape(content.title)+' | MIYAR</title><style>'+style+'</style>'+body(content,locale,record)+'</html>';}
 root.MiyarEnterpriseDocument={body,html};
 if(typeof module!=='undefined')module.exports=root.MiyarEnterpriseDocument;
})(typeof window!=='undefined'?window:globalThis);
